CREATE TABLE albums (id TEXT PRIMARY KEY, name TEXT NOT NULL, sort_name TEXT, year INTEGER, genre TEXT, cover_r2_key TEXT, song_count INTEGER DEFAULT 0, duration INTEGER DEFAULT 0, size INTEGER DEFAULT 0, compilation INTEGER DEFAULT 0, created_at INTEGER DEFAULT (unixepoch()), updated_at INTEGER DEFAULT (unixepoch()));
CREATE TABLE song_masters (id TEXT PRIMARY KEY, album_id TEXT NOT NULL, artist_id TEXT NOT NULL, album_artist_id TEXT, title TEXT NOT NULL, sort_title TEXT, track INTEGER, disc INTEGER, duration INTEGER, genre TEXT, compilation INTEGER DEFAULT 0, participants TEXT, created_at INTEGER DEFAULT (unixepoch()), updated_at INTEGER DEFAULT (unixepoch()), lyrics TEXT, lyrics_rich TEXT, cover_r2_key TEXT);
CREATE TABLE storage_objects (id TEXT PRIMARY KEY, physical_key TEXT NOT NULL UNIQUE, legacy_key TEXT UNIQUE, suffix TEXT NOT NULL, content_type TEXT, size INTEGER NOT NULL DEFAULT 0, etag TEXT, last_modified INTEGER, created_at INTEGER DEFAULT (unixepoch()), updated_at INTEGER DEFAULT (unixepoch()));
CREATE TABLE song_instances (id TEXT PRIMARY KEY, master_id TEXT NOT NULL, source_id TEXT NOT NULL, storage_uri TEXT NOT NULL, suffix TEXT NOT NULL, size INTEGER, missing INTEGER DEFAULT 0, storage_object_id TEXT);
CREATE TABLE storage_entries (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, parent_id TEXT, path TEXT NOT NULL, display_name TEXT NOT NULL, kind TEXT NOT NULL, object_id TEXT, instance_id TEXT, companion_of TEXT);
